import { execSync } from 'child_process';
import { readFileSync, writeFileSync } from 'fs';
import { join } from 'path';
import { fromName } from 'keysym';
import {
  DeadKeyResult,
  KeyBoardLayout,
  KeyboardLayoutKey,
  KeyboardLayoutKeyOutput,
  KlfcResult,
  WSKCode,
} from './model';

// Generated by kbd-dll-parser from the Windows C'hwerty driver (KAD), since
// xkeyboard-config only says which dead-key keysym a key produces, not what
// composing it with a following key results in.
// See https://github.com/andy23512/kbd-dll-parser
const DEAD_KEY_RESULTS: Record<string, DeadKeyResult[]> = JSON.parse(
  readFileSync(join(__dirname, 'assets/dead-keys-fr-bre.json'), 'utf8')
);

const KLFC_RESULT_KEY_POS_TO_WSK_CODE = new Map<string, WSKCode>([
  ['~', 'Backquote'],
  ['1', 'Digit1'],
  ['2', 'Digit2'],
  ['3', 'Digit3'],
  ['4', 'Digit4'],
  ['5', 'Digit5'],
  ['6', 'Digit6'],
  ['7', 'Digit7'],
  ['8', 'Digit8'],
  ['9', 'Digit9'],
  ['0', 'Digit0'],
  ['-', 'Minus'],
  ['+', 'Equal'],
  ['Q', 'KeyQ'],
  ['W', 'KeyW'],
  ['E', 'KeyE'],
  ['R', 'KeyR'],
  ['T', 'KeyT'],
  ['Y', 'KeyY'],
  ['U', 'KeyU'],
  ['I', 'KeyI'],
  ['O', 'KeyO'],
  ['P', 'KeyP'],
  ['[', 'BracketLeft'],
  [']', 'BracketRight'],
  ['A', 'KeyA'],
  ['S', 'KeyS'],
  ['D', 'KeyD'],
  ['F', 'KeyF'],
  ['G', 'KeyG'],
  ['H', 'KeyH'],
  ['J', 'KeyJ'],
  ['K', 'KeyK'],
  ['L', 'KeyL'],
  [';', 'Semicolon'],
  ["'", 'Quote'],
  ['\\', 'Backslash'],
  ['Iso', 'IntlBackslash'],
  ['Z', 'KeyZ'],
  ['X', 'KeyX'],
  ['C', 'KeyC'],
  ['V', 'KeyV'],
  ['B', 'KeyB'],
  ['N', 'KeyN'],
  ['M', 'KeyM'],
  [',', 'Comma'],
  ['.', 'Period'],
  ['/', 'Slash'],
]);

const basePath = '../xkeyboard-config/symbols';

// const result1 = execSync(`klfc --from-xkb "${basePath}/us"`, {encoding:'utf8'});
const result = execSync(`klfc --from-xkb "${basePath}/fr(bre)"`, {
  encoding: 'utf8',
});
const keyboardLayout = convertKlfcResultToKeyboardLayout(JSON.parse(result));
writeFileSync('./output.json', JSON.stringify(keyboardLayout));

function convertKlfcResultToKeyboardLayout(result: KlfcResult): KeyBoardLayout {
  const layoutRecords: KeyBoardLayout['layout'] = {};
  result.keys.forEach((k) => {
    const code = convertKlfcResultKeyPosToWSKCode(k.pos);
    if (!code) {
      return;
    }
    const shiftlevels = k.shiftlevels ?? result.shiftlevels;
    const keyboardLayoutKey: Partial<KeyboardLayoutKey> = {};
    k.letters.forEach((letter, index) => {
      const shiftlevel = shiftlevels[index];
      const normalizedLetter = normalizeKeyOutput(letter);
      switch (shiftlevel) {
        case 'None':
          keyboardLayoutKey.unmodified = normalizedLetter;
          return;
        case 'Shift':
          keyboardLayoutKey.withShift = normalizedLetter;
          return;
        case 'AltGr':
          keyboardLayoutKey.withAltGraph = normalizedLetter;
          return;
        case 'Shift+AltGr':
          keyboardLayoutKey.withShiftAltGraph = normalizedLetter;
          return;
      }
    });
    layoutRecords[code] = keyboardLayoutKey;
  });
  if (layoutRecords.KeyM) {
    layoutRecords.KeyM.unmodified = { type: 'text', value: 'ch' };
    layoutRecords.KeyM.withShift = { type: 'text', value: 'Ch' };
  }
  if (layoutRecords.KeyQ) {
    layoutRecords.KeyQ.unmodified = { type: 'text', value: 'c’h' };
    layoutRecords.KeyQ.withShift = { type: 'text', value: 'C’h' };
  }
  return {
    id: `${result.name}@xkeyboard`,
    name: result.fullName,
    reference:
      'https://xkeyboard-config.freedesktop.org/layouts/analyzer/#?model=iso-60&layout=' +
      encodeURIComponent('fr(bre)'),
    layout: layoutRecords,
  };
}

function convertKlfcResultKeyPosToWSKCode(pos: string): WSKCode | null {
  return KLFC_RESULT_KEY_POS_TO_WSK_CODE.get(pos) ?? null;
}

function normalizeKeyOutput(letter: string): KeyboardLayoutKeyOutput {
  const charMap = {
    abovering: '˚',
  };
  const nameMap = {
    circumflex: 'asciicircum',
    diaeresis: 'diaeresis',
    tilde: 'asciitilde',
    grave: 'grave',
    acute: 'acute',
    macron: 'macron',
    abovedot: 'abovedot',
  };
  if (
    [
      'circumflex',
      'diaeresis',
      'tilde',
      'abovering',
      'grave',
      'acute',
      'macron',
      'abovedot',
    ].includes(letter)
  ) {
    console.log(
      charMap[letter as keyof typeof charMap] ||
        String.fromCodePoint(
          fromName(nameMap[letter as keyof typeof nameMap])?.unicode as number
        ),
      '◌' + String.fromCodePoint(fromName('dead_' + letter)?.unicode as number)
    );
    const value =
      charMap[letter as keyof typeof charMap] ||
      String.fromCodePoint(
        fromName(nameMap[letter as keyof typeof nameMap])?.unicode as number
      );
    const deadKeyResults = DEAD_KEY_RESULTS[value];
    return {
      type: 'dead-key',
      value,
      ...(deadKeyResults ? { deadKeyResults } : {}),
    };
  }
  return { type: 'text', value: letter };
}
